import{z as i,x as n,o as e,c as d,q as r,j as s,D as E,d as t,s as B,S as o,b as l}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"SPLADE","description":"","frontmatter":{"title":"SPLADE","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/splade.md","filePath":"llm/splade.md","lastUpdated":1791413859000}'),p={name:"llm/splade.md"};function m(D,a,F,h,C,S){const A=n("Mermaid");return e(),d("div",null,[a[2]||(a[2]=r('<h1 id="splade" tabindex="-1">SPLADE <a class="header-anchor" href="#splade" aria-label="Permalink to &quot;SPLADE&quot;">​</a></h1><div class="epigraph"><p>让编码器对词表维预测稀疏权重，倒排里就会出现「没写在文里但该被检索到」的扩展词。词法通道由此可学习，而不只靠 BM25 计数。</p><footer>—— Formal 等 SPLADE</footer></div><p><a href="/llm/bm25-sparse">上一课</a>的词袋不能扩同义。查询扩展与同义词表是手工的。Formal 等人的 SPLADE 用预训练语言模型对每个文档（和查询）预测一个词表那么长的稀疏向量，非零维相当于加权后的词，可写入倒排。缺口是把「可学习稀疏」从稠密双塔里拆出来。后课 MTEB 会同时考稀疏、稠密与指令嵌入，不要混成一种模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BM25 只激活文档里出现过的词。用户写「心肌梗死」，文档写「heart attack」，字面零命中。稠密能对上，但标识符又弱。SPLADE 希望：稀疏向量在「心肌梗死」维上有权重，即使原文是英文医学同义。它仍走倒排，延迟与可解释性接近词法，而不是 ANN。</p><p><span class="marginnote">一句话翻译 SPLADE：把「该被哪些词检索到」写进一个词表长度的稀疏向量——每一维对应一个具体的词，非零维就是「用这个词能找到这篇文档」，数值是它的冲击力；这些非零维再当普通词条写回倒排索引。</span></p><p>训练要用对比或蒸馏（向交叉编码器看齐），并对向量加稀疏正则，否则退化为稠密的低效版本：几乎每维都非零，倒排爆炸。</p><p><span class="marginnote">稀疏维是词表下标，人可以读出「模型用哪些词扩展了文档」。这是调试召回的接口，不是保证扩展正确。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对输入做 MLM 式 logits，经激活（如 log-saturation）与池化得到词表维权重，再 L1 / FLOPS 正则压非零数。查询与文档可非对称：查询更短更稀疏。索引：把非零维当 term、权重当冲击值，用学习到的分数代替 BM25 公式。推理延迟取决于平均非零数，必须当指标报。</p><p><span class="marginnote">数字感受稀疏度的意义：3 万词表的稠密向量若每维非零，倒排里每篇文档要挂 3 万个词条，posting list 直接爆炸；SPLADE 把平均非零压到几十至几百个后，倒排长度回到 BM25 同量级，检索延迟才有得比。</span></p>',11)),(e(),s(o,null,{default:E(()=>[B(A,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%22%5D%20--%3E%20LM%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%20logits%22%5D%0A%20%20LM%20--%3E%20SP%5B%22%E7%A8%80%E7%96%8F%E8%AF%8D%E8%A1%A8%E5%90%91%E9%87%8F%22%5D%0A%20%20SP%20--%3E%20INV%5B%22%E5%80%92%E6%8E%92%22%5D%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%E7%A8%80%E7%96%8F%E5%90%91%E9%87%8F%22%5D%20--%3E%20SC%5B%22%E7%82%B9%E7%A7%AF%20%2F%20%E5%80%92%E6%8E%92%E6%B1%82%E5%88%86%22%5D%0A%20%20INV%20--%3E%20SC%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[t("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"正则迫使模型只点亮少量扩展词。对比损失要求这些词能把正例从难负例里分开，于是点亮的是有判别力的同义与相关词，而不只是高频词。若正则过强，退回近乎字面 BM25；过弱，变成昂贵稠密。与难负例课同样：假相关扩展会伤害精度。",-1)),(e(),s(o,null,{default:E(()=>[B(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%EF%BC%9A%E5%BF%83%E8%82%8C%E6%A2%97%E6%AD%BB%22%5D%20--%3E%20S%7B%22%E7%A8%80%E7%96%8F%E6%AD%A3%E5%88%99%E5%BC%BA%E5%BA%A6%E6%97%8B%E9%92%AE%22%7D%0A%20%20S%20--%3E%7C%E6%8B%A7%E5%BE%97%E8%BF%87%E5%BC%BA%7C%20BM%5B%22%E5%8F%AA%E7%82%B9%E4%BA%AE%E5%8E%9F%E8%AF%8D%EF%BC%9A%E9%80%80%E5%9B%9E%20BM25%EF%BC%8C%E5%90%8C%E4%B9%89%E8%AF%8D%E5%85%A8%E4%B8%A2%22%5D%0A%20%20S%20--%3E%7C%E9%80%82%E4%B8%AD%7C%20GD%5B%22%E7%82%B9%E4%BA%AE%E5%B0%91%E9%87%8F%E5%88%A4%E5%88%AB%E6%80%A7%E6%89%A9%E5%B1%95%E8%AF%8D%EF%BC%9Aheart%20attack%20%E4%B9%9F%E5%91%BD%E4%B8%AD%22%5D%0A%20%20S%20--%3E%7C%E6%8B%A7%E5%BE%97%E8%BF%87%E5%BC%B1%7C%20DE%5B%22%E5%87%A0%E4%B9%8E%E6%AF%8F%E7%BB%B4%E9%9D%9E%E9%9B%B6%EF%BC%9A%E5%80%92%E6%8E%92%E7%88%86%E7%82%B8%EF%BC%8C%E9%80%80%E5%8C%96%E6%88%90%E4%BD%8E%E6%95%88%E7%A8%A0%E5%AF%86%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">直觉类比：SPLADE 像一位懂术语的图书管理员替你改检索卡——你写「心肌梗死」，他悄悄添上「heart attack」等几张标签；但标签预算（稀疏正则）有限，不许把整本同义词典都贴上去。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>词表是分词器词表，对未登录标识符仍弱——keyword 字段与 BM25 通道仍值得保留，混合检索并不过时。下一课 MTEB：在统一任务套件上比较这些嵌入家族。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SPLADE 学习稀疏词表权重，倒排可含扩展词。</li><li>稀疏正则是可用性条件；非零数要当延迟指标。</li><li>不替代 BM25 标识符字段，常作混合一路。</li><li>出处：Formal 等 SPLADE。</li></ul>',5))])}const _=i(p,[["render",m]]);export{P as __pageData,_ as default};
